sparql_response:
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?mother ?deathPlace WHERE {
  dbr:Sancha_of_Castile,_Queen_of_Navarre dbp:mother ?mother .
  OPTIONAL { ?mother dbp:deathPlace ?dp . }
  OPTIONAL { ?mother dbo:deathPlace ?dp2 . }
  BIND (COALESCE(?dp, ?dp2) AS ?deathPlace)
}
LIMIT 100

